import{_ as o,a0 as a,w as r,s as d,ao as n,I as p,a1 as s,A as i,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"一个通过 IRC 管理所有聊天的开源聊天工具 | LCTT x X-CMD","titleTemplate":false,"description":"一个通过 IRC 管理所有聊天的开源聊天工具 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一个通过 IRC 管理所有聊天的开源聊天工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一个通过 IRC 管理所有聊天的开源聊天工具 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200119 One open source chat tool to rule them all","title":"一个通过 IRC 管理所有聊天的开源聊天工具","tag":"202002","desc":""},"relativePath":"202002/20200119 One open source chat tool to rule them all.md","filePath":"[post].md"}'),u={name:"202002/20200119 One open source chat tool to rule them all.md"};function g(k,t,b,m,f,h){const l=a("Link");return r(),d("div",null,[t[35]||(t[35]=n('<h1 id="一个通过-irc-管理所有聊天的开源聊天工具" tabindex="-1">一个通过 IRC 管理所有聊天的开源聊天工具 <a class="header-anchor" href="#一个通过-irc-管理所有聊天的开源聊天工具" aria-label="Permalink to “一个通过 IRC 管理所有聊天的开源聊天工具”">​</a></h1><blockquote><p>BitlBee 将多个聊天应用集合到一个界面中。在我们的 20 个使用开源提升生产力的系列的第九篇文章中了解如何设置和使用 BitlBee。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/05/123636dw8uw34mbkqzmw84.jpg" alt=""></p><p>去年，我在 19 天里给你介绍了 19 个新（对你而言）的生产力工具。今年，我换了一种方式：使用你在使用或者还没使用的工具，构建一个使你可以在新一年更加高效的环境。</p><h3 id="将所有聊天都放到-bitlbee-中" tabindex="-1">将所有聊天都放到 BitlBee 中 <a class="header-anchor" href="#将所有聊天都放到-bitlbee-中" aria-label="Permalink to “将所有聊天都放到 BitlBee 中”">​</a></h3><p>即时消息和聊天已经成为网络世界的主要内容。如果你像我一样，你可能打开五六个不同的应用与你的朋友、同事和其他人交谈。关注所有聊天真的很痛苦。谢天谢地，你可以使用一个应用（好吧，是两个）将这些聊天整个到一个地方。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-1.png" alt="BitlBee on XChat" title="BitlBee on XChat"></p>',7)),p("p",null,[s(l,{href:"https://www.bitlbee.org/"},{default:i(()=>[...t[0]||(t[0]=[e("BitlBee",-1)])]),_:1}),t[1]||(t[1]=e(" 是作为服务运行的应用，它可以将标准的 IRC 客户端与大量的消息服务进行桥接。而且，由于它本质上是 IRC 服务器，因此你可以选择很多客户端。",-1))]),t[36]||(t[36]=n('<p>BitlBee 几乎包含在所有 Linux 发行版中。在 Ubuntu 上安装（我选择的 Linux 桌面），类似这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install bitlbee-libpurple</span></span></code></pre></div><p>在其他发行版上，包名可能略有不同，但搜索 “bitlbee” 应该就能看到。</p>',3)),p("p",null,[t[4]||(t[4]=e("你会注意到我用的 libpurple 版的 BitlBee。这个版本能让我使用 ",-1)),s(l,{href:"https://developer.pidgin.im/wiki/WhatIsLibpurple"},{default:i(()=>[...t[2]||(t[2]=[e("libpurple",-1)])]),_:1}),t[5]||(t[5]=e(" 即时消息库中提供的所有协议，该库最初是为 ",-1)),s(l,{href:"http://pidgin.im/"},{default:i(()=>[...t[3]||(t[3]=[e("Pidgin",-1)])]),_:1}),t[6]||(t[6]=e(" 开发的。",-1))]),p("p",null,[t[8]||(t[8]=e("安装完成后，服务应会自动启动。现在，使用一个 IRC 客户端（图片中为 ",-1)),s(l,{href:"http://xchat.org/"},{default:i(()=>[...t[7]||(t[7]=[e("XChat",-1)])]),_:1}),t[9]||(t[9]=e("），我可以连接到端口 6667（标准 IRC 端口）上的服务。",-1))]),t[37]||(t[37]=n('<p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-2.png" alt="Initial BitlBee connection" title="Initial BitlBee connection"></p><p>你将自动连接到控制频道 &amp;bitlbee。此频道对于你是独一无二的，在多用户系统上每个人都有一个自己的。在这里你可以配置该服务。</p><p>在控制频道中输入 <code>help</code>，你可以随时获得完整的文档。浏览它，然后使用 <code>register</code> 命令在服务器上注册帐户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>register &lt;mypassword&gt;</span></span></code></pre></div><p>现在，你在服务器上所做的任何配置更改（IM 帐户、设置等）都将在输入 <code>save</code> 时保存。每当你连接时，使用 <code>identify &lt;mypassword&gt;</code> 连接到你的帐户并加载这些设置。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_9-3.png" alt="purple settings" title="purple settings"></p>',6)),p("p",null,[t[11]||(t[11]=e("命令 ",-1)),t[12]||(t[12]=p("code",null,"help purple",-1)),t[13]||(t[13]=e(" 将显示 libpurple 提供的所有可用协议。例如，我安装了 ",-1)),s(l,{href:"https://github.com/majn/telegram-purple"},{default:i(()=>[...t[10]||(t[10]=[e("telegram-purple",-1)])]),_:1}),t[14]||(t[14]=e(" 包，它增加了连接到 Telegram 的能力。我可以使用 ",-1)),t[15]||(t[15]=p("code",null,"account add",-1)),t[16]||(t[16]=e(" 命令将我的电话号码作为帐户添加。",-1))]),t[38]||(t[38]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>account add telegram +15555555</span></span></code></pre></div><p>BitlBee 将显示它已添加帐户。你可以使用 <code>account list</code> 列出你的帐户。因为我只有一个帐户，我可以通过 <code>account 0 on</code> 登录，它会进行 Telegram 登录，列出我所有的朋友和聊天，接下来就能正常聊天了。</p>',2)),p("p",null,[t[18]||(t[18]=e("但是，对于 Slack 这个最常见的聊天系统之一呢？你可以安装 ",-1)),s(l,{href:"https://github.com/dylex/slack-libpurple"},{default:i(()=>[...t[17]||(t[17]=[e("slack-libpurple",-1)])]),_:1}),t[19]||(t[19]=e(" 插件，并且对 Slack 执行同样的操作。如果你不愿意编译和安装这些，这可能不适合你。",-1))]),t[39]||(t[39]=n(`<p>按照插件页面上的说明操作，安装后重新启动 BitlBee 服务。现在，当你运行 <code>help purple</code> 时，应该会列出 Slack。像其他协议一样添加一个 Slack 帐户。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>account add slack ksonney@myslack.slack.com</span></span>
<span class="line"><span>account 1 set password my_legcay_API_token</span></span>
<span class="line"><span>account 1 on</span></span></code></pre></div><p>你知道么，你已经连接到 Slack 中，你可以通过 <code>chat add</code> 命令添加你感兴趣的 Slack 频道。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chat add 1 happyparty</span></span></code></pre></div><p>将 Slack 频道 happyparty 添加为本地频道 #happyparty。现在可以使用标准 IRC <code>/join</code> 命令访问该频道。这很酷。</p><p>BitlBee 和 IRC 客户端帮助我的（大部分）聊天和即时消息保存在一个地方，并减少了我的分心，因为我不再需要查找并切换到任何一个刚刚找我的应用上。</p><hr>`,7)),p("p",null,[t[21]||(t[21]=e("via: ",-1)),s(l,{href:"https://opensource.com/article/20/1/open-source-chat-tool"},{default:i(()=>[...t[20]||(t[20]=[e("https://opensource.com/article/20/1/open-source-chat-tool",-1)])]),_:1})]),p("p",null,[t[26]||(t[26]=e("作者：",-1)),s(l,{href:"https://opensource.com/users/ksonney"},{default:i(()=>[...t[22]||(t[22]=[e("Kevin Sonney",-1)])]),_:1}),t[27]||(t[27]=e(" 选题：",-1)),s(l,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[23]||(t[23]=[e("lujun9972",-1)])]),_:1}),t[28]||(t[28]=e(" 译者：",-1)),s(l,{href:"https://github.com/geekpi"},{default:i(()=>[...t[24]||(t[24]=[e("geekpi",-1)])]),_:1}),t[29]||(t[29]=e(" 校对：",-1)),s(l,{href:"https://github.com/wxy"},{default:i(()=>[...t[25]||(t[25]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[32]||(t[32]=e("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[30]||(t[30]=[e("LCTT",-1)])]),_:1}),t[33]||(t[33]=e(" 原创编译，",-1)),s(l,{href:"https://linux.cn/"},{default:i(()=>[...t[31]||(t[31]=[e("Linux中国",-1)])]),_:1}),t[34]||(t[34]=e(" 荣誉推出",-1))])])}const B=o(u,[["render",g]]);export{y as __pageData,B as default};
